import {socialAccounts} from './social-profile.js';
/** Editorial prototype views. Static example content only; route and citation behavior stays in app.js. */
const number=i=>String(i+1).padStart(2,'0');
const diagram=(labels,caption)=>`<figure class="field-diagram"><div>${labels.map((label,i)=>`<span><small>${number(i)}</small>${label}</span>`).join('<b aria-hidden="true">↗</b>')}</div><figcaption>${caption}</figcaption></figure>`;
const titles={explore:['让探索有意义，','而不挡住阅读。'],sources:['一个回答，','也应该有来路。'],boundaries:['给 Agent，','一条清楚的边界。']};
const notes={explore:['体验不是一道入场考试。','在一个可玩的个人网站里，最值得设计的，也许是离开的自由。','场景负责引起好奇，内容负责让人留下。'],sources:['好答案，应该允许被追问。','顺着一条引用回到原文，是从“听起来可信”走向“可以核对”的一步。','让每一个结论，都有可以回去的地方。'],boundaries:['一句“帮我改”，不等于“替我发布”。','把意图、提案和执行分开，让每一次改变都有清楚的起点与边界。','信任来自可见的过程，而不是一句成功。']};
export function detailView(type,item,{back,update=''}){
 const project=type==='project',mars=item.id==='mars',parts=item.sections||item.parts;
 const index=project?item.num:number(['explore','sources','boundaries'].indexOf(item.id));
 const next=project?(mars?['project/index','线索索引']:['project/mars','远行手记']):({explore:['article/sources','一个回答，也应该有来路'],sources:['article/boundaries','给 Agent 一条清楚的边界'],boundaries:['article/explore','让探索有意义，而不挡住阅读']}[item.id]);
 const toc=`<nav class="chapter-nav" aria-label="本页章节"><span class="folio-label">IN THIS ${project?'PROJECT':'NOTE'}</span>${parts.map(([h],i)=>`<button data-section="section-${i}"><small>${number(i)}</small>${h}<span>↗</span></button>`).join('')}<p>设计示例 · 非真实履历<br>内容与功能仍在原型阶段</p></nav>`;
 const hero=project?`<div class="case-heading"><div><span class="folio-label">SELECTED WORK / ${index}</span><h1>${item.name}<span>${mars?'A small departure.':'Follow the evidence.'}</span></h1></div><div class="case-deck"><p>${item.desc}</p><span>${item.kind}</span></div></div><figure class="case-cover ${mars?'cover-mars':'cover-index'}">${mars?'<img src="mars-panorama.png" alt="远行手记的火星地表与连绵山坡"><span class="cover-caption">一段旅程，从好奇开始。<small>THE DEPARTURE / MARS FIELDNOTES</small></span>':`<div class="index-composition"><span class="index-thread" aria-hidden="true"></span><div class="source-slip"><small>01 / QUESTION</small><strong>一个念头，<br>从哪里来？</strong><span>Follow your curiosity ↗</span></div><div class="source-slip"><small>02 / SOURCE</small><strong>原文里的<br>那条线索。</strong><span>Reading → Understanding</span></div><div class="source-slip"><small>03 / CONNECTION</small><strong>问题与出处，<br>在这里相遇。</strong><span>INDEX / 概念演示</span></div></div>`}<figcaption>${mars?'FIG. 01 — 火星场景视觉 / 原型素材':'FIG. 01 — 从问题到原文 / 概念排演'}<span>${index} / FIELDNOTES</span></figcaption></figure><div class="case-facts"><div><small>FORMAT</small><span>${mars?'可探索的个人网站':'可追溯的阅读工具'}</span></div><div><small>FOCUS</small><span>${mars?'空间叙事 · 内容阅读':'问题 · 引用 · 原文'}</span></div><div><small>STATUS</small><span>${mars?'交互原型':'虚构概念示例'}</span></div></div>`:`<div class="note-heading"><div class="note-edition"><span class="folio-label">FIELDNOTES / DESIGN ESSAYS</span><span>随手记 · 第 ${index} 篇</span></div><h1>${titles[item.id].map(t=>`<span>${t}</span>`).join('')}</h1><p>${item.summary}</p><div class="note-byline"><span>文字与思考 / 设计示例</span><span>3 个章节 · ${index.padStart(3,'0')}</span></div></div><div class="note-frontispiece note-${item.id}" aria-hidden="true"><span class="folio-label">${item.id==='explore'?'THE FREEDOM TO EXPLORE':item.id==='sources'?'A TRACE OF THOUGHT':'INTENTION → PERMISSION'}</span><div class="editorial-glyph">${item.id==='explore'?'↗':item.id==='sources'?'[ ↗ ]':'→ |'}</div><span class="frontispiece-note">${notes[item.id][0]}</span></div>`;
 const sections=parts.map(([h,p],i)=>`<section class="editorial-section" id="section-${i}"><div class="section-heading"><span>${number(i)}</span><h2>${h}</h2></div><p>${p}</p>${i===0?(project?diagram(mars?['探索火星','发现船票','带着问题归航']:['提出问题','发现来源','回到原文'],mars?'探索路线 / 普通阅读始终有独立入口':'阅读路径 / 原型仅使用公开示例'): `<p class="editorial-aside">${notes[item.id][1]}</p>`):''}${i===1?(project?`<div class="design-pair"><div><small>${mars?'FOR THE CURIOUS':'READ'}</small><h3>${mars?'留一点探索的余地。':'先找到值得读的内容。'}</h3><p>${mars?'动手、发现、出发。每一个动作，都让下一步变得可见。':'问题提供方向，主题索引提供线索，原文保留完整语境。'}</p></div><div><small>${mars?'FOR THE FOCUSED':'VERIFY'}</small><h3>${mars?'也留一条直接的路。':'再核对答案的依据。'}</h3><p>${mars?'不需要完成游戏，也能看作品、读文章、了解这个网站。':'引用落到具体段落，而不是只给一个无从查找的链接。'}</p></div></div>`:`<blockquote>${notes[item.id][2]}</blockquote>`):''}</section>`).join('');
 return `<article class="editorial ${project?'case-study':'design-note'}"><div class="editorial-top">${back}<span class="folio-label">${project?'WORK ARCHIVE':'THE NOTEBOOK'} / ${index}</span></div>${hero}<div class="editorial-layout">${toc}<div class="editorial-body">${project?`<p class="case-introduction">${item.body}</p>${update}`:''}${sections}<div class="endnote"><span>✳</span><p>本文为原型设计示例，不代表站长的真实经历、项目成果或已发表文章。</p></div><div class="reading-conversation"><span class="folio-label">KEEP THE CONVERSATION GOING</span><h2>还有一点好奇？</h2><button data-action="ask-context" data-context="${project?'项目：'+item.name:'文章：'+item.title}">问问 AI，关于这${project?'个项目':'篇文章'} <span>↗</span></button></div></div></div><button class="next-story" data-route="${next[0]}"><span class="folio-label">${project?'NEXT PROJECT':'NEXT NOTE'} / 继续翻阅</span><strong>${next[1]}</strong><span class="next-arrow">↗</span></button></article>`;
}
export function aboutView(back){return `<article class="editorial letter-page"><div class="editorial-top">${back}<span class="folio-label">A NOTE ABOUT ME</span></div><div class="letter-layout"><aside class="letter-margin"><span class="letter-monogram">F<span>↗</span></span><span class="folio-label">BEHIND THE FIELDNOTES</span><p>关于做作品的人，<br>以及尚未写下的故事。</p><span class="letter-stamp">待本人补充<br>PERSONAL NOTE</span></aside><div class="letter-paper"><span class="folio-label">你好，欢迎来坐坐。</span><h1>不止于作品，<br>也关于<br><em>做作品的人。</em></h1><p class="letter-lead">保留好奇，做出东西，记录过程。</p><p>火星是一个故事入口，文章和项目承载内容。这张信纸，留给你的真实介绍：你关注什么、正在做什么，以及愿意和别人讨论什么。</p><div class="letter-details"><span>01 / 当前关注</span><p>留给正在探索的问题与方向。</p><span>02 / 走过的路</span><p>留给可核对的经历与真实作品。</p><span>03 / 保持联系</span><p>留给本人批准公开的联系渠道。</p></div><p class="content-disclosure">公开姓名：黄凌波。职业与履历待本人补充，这里不代写个人经历。</p><div class="letter-signoff"><span>故事，慢慢写。</span><button data-route="contact">交换一个想法 ↗</button></div></div></div></article>`}
export function contactView(back){return `<article class="editorial contact-editorial"><div class="editorial-top">${back}<span class="folio-label">AN OPEN CHANNEL</span></div><span class="contact-star" aria-hidden="true">✳</span><span class="folio-label">GOOD THINGS BEGIN WITH A CONVERSATION</span><h1>有想法，<br>就值得<em>交换。</em></h1><p>关于作品、文字，或一个还没想清楚的问题。</p><div class="contact-line"><span>联系渠道</span><strong>待本人提供</strong><span>↗</span></div><p class="content-disclosure">邮箱与社交账号确认后会出现在这里。原型不展示虚构地址，也不收集访客信息。</p><button class="contact-work" data-route="projects">在那之前，先看看作品 <span>↗</span></button></article>`}

/** Missing handles are honest non-interactive entries, never guessed profile URLs. */
export function socialView(back){return `<article class="editorial social-page"><div class="editorial-top">${back}<span class="folio-label">ELSEWHERE / 保持连接</span></div><div class="social-intro"><div><span class="folio-label">A FEW PLACES TO FIND ME</span><h1>黄凌波<span>在别处，也能遇见。</span></h1></div><p>作品、记录、正在发生的念头。<br>选择一个你习惯的平台。</p></div><div class="social-directory">${socialAccounts.map((a,i)=>{const content=`<span class="social-index">${number(i)}</span><span class="social-symbol" aria-hidden="true">${a.mark}</span><span class="social-platform"><strong>${a.name}</strong><small>${a.label}</small></span><span class="social-handle">${a.url?a.handle:'主页地址待补充'}</span><span class="social-arrow" aria-hidden="true">${a.url?'↗':'—'}</span>`;return a.url?`<a class="social-entry" href="${a.url}" target="_blank" rel="noopener noreferrer" aria-label="黄凌波的 ${a.name} 主页（新标签页）">${content}</a>`:`<div class="social-entry is-pending">${content}</div>`}).join('')}</div><div class="social-footnote"><span>仅跳转本人确认的主页。</span><span>链接在新标签页打开 ↗</span></div></article>`}
